import type { PageCacheRoute } from "./policy";

const quote = (value: string): string =>
  `'${value.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;

const HEADER = `/* oxlint-disable */

// This file is generated by VitNode. Do not edit it, and do not format it.
//
// It is rewritten by the \`vitnode:plugin-routes\` Vite plugin on every
// \`vite dev\` and \`vite build\`: every page route of this app, with the HTML
// cache policy that applies to it once the routes' own \`cache\` options and
// \`vitNodeConfig.pageCache\` have been resolved. \`vitnode build\` reports the
// same table, so the report and the server cannot disagree.
//
// Routes without \`maxAge\` are never cached. They are listed anyway, so a more
// specific uncached route is never answered by a cached pattern beside it.
//
// \`pageCacheBuildId\` is replaced at build time with an id unique to that build,
// so two deployments sharing one cache never serve each other's HTML.

import type { PageCacheRouteTable } from '@vitnode/core/page-cache/policy'

`;

const routeLiteral = (route: PageCacheRoute): string =>
  [
    `path: ${quote(route.path)}`,
    ...(route.maxAge === undefined ? [] : [`maxAge: ${String(route.maxAge)}`]),
    ...(route.staleWhileRevalidate === undefined
      ? []
      : [`staleWhileRevalidate: ${String(route.staleWhileRevalidate)}`]),
  ].join(", ");

export const generatePageCacheSource = (
  routes: readonly PageCacheRoute[],
): string =>
  `${HEADER}export const pageCacheBuildId: string = import.meta.env.VITNODE_BUILD_ID\n\nexport const pageCacheRoutes: PageCacheRouteTable = [\n${routes
    .map(route => `  { ${routeLiteral(route)} },\n`)
    .join("")}]\n`;
